INSERT INTO "feedbacks" ("id", "code", "title", "content", "sender_name", "sender_email", "status", "impact_level", "priority_score", "similarity_score", "is_duplicate_confirmed", "created_at", "updated_at", "assigned_to_id", "author_id", "source_id", "product_id", "ai_summary", "duplicate_of_id") VALUES (53, 'FB-0053', 'Cho phép đặt hẹn giờ giao cố định vào sáng hôm sau', 'Muốn đặt sẵn từ tối hôm trước để 11h30 trưa hôm sau quán tự giao.', 'Nguyễn Hoài An', 'an.nguyen@gmail.com', 'NEW', 'MEDIUM', NULL, NULL, FALSE, '2026-11-12T13:17:42.051691+00:00'::timestamptz, '2026-11-14T01:17:42.142377+00:00'::timestamptz, NULL, 5, 1, 1, '', NULL);
