INSERT INTO "insight_groups" ("id", "code", "title", "description", "possible_causes", "ai_recommendations", "draft_customer_reply", "volume_score", "impact_score", "severity_score", "priority_score", "priority_level", "status", "verification_status", "feedback_count", "created_at", "assigned_to_id", "product_id") VALUES (1, 'INS-001', 'Lỗi & trục trặc quy trình thanh toán đơn hàng', 'Nhóm gồm 10 phản hồi mức độ nghiêm trọng cao về việc không thể hoàn tất thanh toán qua thẻ Visa/ATM, ví MoMo/ZaloPay hoặc bị trừ tiền nhưng đơn chưa xác nhận.', '["Giả thuyết cần kiểm tra: timeout kết nối tới cổng thanh toán giờ cao điểm trưa (11h30–13h00).", "Giả thuyết cần kiểm tra: webhook đối soát trạng thái giao dịch giữa ví điện tử và hệ thống đơn hàng chưa đồng bộ kịp."]'::jsonb, '["Kiểm tra log giao dịch thất bại theo cổng thanh toán và bổ sung cơ chế idempotency + retry an toàn.", "Hiển thị màn hình trạng thái chờ đối soát rõ ràng kèm nút kiểm tra lại giao dịch / hoàn tiền tự động."]'::jsonb, 'Chào bạn,
INSERT INTO "insight_groups" ("id", "code", "title", "description", "possible_causes", "ai_recommendations", "draft_customer_reply", "volume_score", "impact_score", "severity_score", "priority_score", "priority_level", "status", "verification_status", "feedback_count", "created_at", "assigned_to_id", "product_id") VALUES (2, 'INS-002', 'Giao hàng chậm và sai lệch thời gian dự kiến (ETA)', '9 phản hồi phản ánh thời gian giao hàng thực tế chậm hơn 25–40 phút so với ETA hiển thị trên app, đặc biệt vào khung giờ cao điểm trưa và ngày mưa.', '["Giả thuyết cần kiểm tra: mô hình ước lượng ETA hiện tại chưa cập nhật trọng số kẹt xe và thời gian quán chuẩn bị món giờ cao điểm.", "Giả thuyết cần kiểm tra: thuật toán ghép nhiều đơn cho cùng tài xế làm kéo dài lộ trình giao."]'::jsonb, '["Hiệu chỉnh mô hình dự báo ETA theo dữ liệu lịch sử từng khung giờ và khu vực.", "Gửi thông báo chủ động khi đơn dự kiến trễ quá 10 phút kèm lý do minh bạch."]'::jsonb, 'Chào bạn,
INSERT INTO "insight_groups" ("id", "code", "title", "description", "possible_causes", "ai_recommendations", "draft_customer_reply", "volume_score", "impact_score", "severity_score", "priority_score", "priority_level", "status", "verification_status", "feedback_count", "created_at", "assigned_to_id", "product_id") VALUES (3, 'INS-003', 'Thiếu hoặc chậm thông báo trạng thái đơn và khi tài xế đến', '8 phản hồi ghi nhận người dùng không nhận được push notification khi quán xác nhận, tài xế nhắn tin hoặc khi shipper đã tới điểm giao.', '["Giả thuyết cần kiểm tra: token FCM/APNs trên iOS 18 và một số thiết bị Android chưa được làm mới đúng chu kỳ.", "Giả thuyết cần kiểm tra: sự kiện cập nhật vị trí tài xế vào bán kính 200m chưa kích hoạt cảnh báo đẩy."]'::jsonb, '["Kiểm tra tỷ lệ delivery push notification theo hệ điều hành và thêm kênh thông báo in-app realtime.", "Bổ sung thông báo nhắc nhận hàng khi tài xế cách điểm giao 200m."]'::jsonb, 'Chào bạn,
INSERT INTO "insight_groups" ("id", "code", "title", "description", "possible_causes", "ai_recommendations", "draft_customer_reply", "volume_score", "impact_score", "severity_score", "priority_score", "priority_level", "status", "verification_status", "feedback_count", "created_at", "assigned_to_id", "product_id") VALUES (4, 'INS-004', 'Khó khăn khi áp dụng mã giảm giá & voucher khuyến mãi', '8 phản hồi cho biết voucher bị từ chối không rõ lý do, tự động mất khi sửa giỏ hàng hoặc số tiền giảm chưa rõ ràng.', '["Giả thuyết cần kiểm tra: UI hiện chỉ trả mã lỗi chung chung mà không nêu điều kiện còn thiếu (giá trị đơn tối thiểu, phương thức thanh toán).", "Giả thuyết cần kiểm tra: sự kiện cập nhật giỏ hàng làm reset trạng thái voucher đã chọn."]'::jsonb, '["Hiển thị rõ lý do không đủ điều kiện ngay dưới từng voucher và hỗ trợ tự động chọn mã ưu đãi tốt nhất.", "Giữ nguyên trạng thái voucher hợp lệ khi chỉnh sửa món trong giỏ hàng."]'::jsonb, 'Chào bạn,
INSERT INTO "insight_groups" ("id", "code", "title", "description", "possible_causes", "ai_recommendations", "draft_customer_reply", "volume_score", "impact_score", "severity_score", "priority_score", "priority_level", "status", "verification_status", "feedback_count", "created_at", "assigned_to_id", "product_id") VALUES (5, 'INS-005', 'Sai lệch định vị GPS chung cư và tìm kiếm món không dấu', '7 phản hồi về ghim GPS lệch sang tòa nhà kế bên, tìm kiếm món không dấu chưa chuẩn và thiếu lưu ghi chú cổng giao hàng.', '["Giả thuyết cần kiểm tra: dữ liệu POI tòa nhà/chung cư ở một số khu đô thị mới chưa có điểm đón chi tiết.", "Giả thuyết cần kiểm tra: bộ tìm kiếm full-text chưa chuẩn hóa đồng nhất chuỗi tiếng Việt không dấu."]'::jsonb, '["Cho phép lưu ghi chú cổng/tòa nhà gắn với từng địa chỉ đã lưu và cho phép kéo ghim mượt hơn.", "Bổ sung index tìm kiếm tiếng Việt không dấu kết hợp khoảng cách ưu tiên quán gần."]'::jsonb, 'Chào bạn,
INSERT INTO "roadmap_items" ("id", "code", "title", "description", "public_description", "status", "visibility", "quarter", "progress_percent", "updated_at", "owner_id", "product_id") VALUES (1, 'RM-001', 'Ổn định cổng thanh toán & đối soát tự động giao dịch treo', 'Nâng cấp luồng thanh toán thẻ/ví với idempotency key, webhook retry và màn hình đối soát trạng thái tức thì.', 'Nâng cấp độ ổn định khi thanh toán bằng thẻ và ví điện tử, bổ sung thông báo trạng thái rõ ràng khi mạng chậm.', 'IN_PROGRESS', 'PUBLIC', 'Q4 2026', 65, '2026-11-14T01:17:42.166918+00:00'::timestamptz, 3, 1);
INSERT INTO "roadmap_items" ("id", "code", "title", "description", "public_description", "status", "visibility", "quarter", "progress_percent", "updated_at", "owner_id", "product_id") VALUES (2, 'RM-002', 'Dự báo thời gian giao hàng thông minh (Smart ETA v2)', 'Áp dụng dữ liệu khung giờ cao điểm, thời tiết và tốc độ chuẩn bị món tại quán để dự đoán ETA chính xác hơn.', 'Cải thiện độ chính xác của thời gian giao hàng dự kiến và cảnh báo sớm nếu đơn có nguy cơ giao chậm.', 'PLANNED', 'PUBLIC', 'Q4 2026', 15, '2026-11-14T01:17:42.167730+00:00'::timestamptz, 3, 1);
INSERT INTO "roadmap_items" ("id", "code", "title", "description", "public_description", "status", "visibility", "quarter", "progress_percent", "updated_at", "owner_id", "product_id") VALUES (3, 'RM-003', 'Nâng cấp hệ thống Push Notification & nhắc nhận hàng 200m', 'Sửa lỗi mất token thông báo trên iOS 18 và gửi thông báo đẩy kèm âm báo khi tài xế sắp tới điểm giao.', 'Đảm bảo thông báo trạng thái đơn và nhắc nhận hàng khi tài xế đến nơi luôn hiển thị đúng lúc.', 'PLANNED', 'PUBLIC', 'Q1 2027', 10, '2026-11-14T01:17:42.168224+00:00'::timestamptz, 4, 1);
INSERT INTO "roadmap_items" ("id", "code", "title", "description", "public_description", "status", "visibility", "quarter", "progress_percent", "updated_at", "owner_id", "product_id") VALUES (4, 'RM-004', 'Tự động gợi ý Voucher tối ưu & hiển thị rõ điều kiện', 'Hiển thị điều kiện chi tiết của từng mã giảm giá, giữ voucher khi sửa giỏ hàng và tự đề xuất mã giảm sâu nhất.', 'Tự động gợi ý mã khuyến mãi tốt nhất và giải thích rõ ràng điều kiện áp dụng tại giỏ hàng.', 'COMPLETED', 'PUBLIC', 'Q4 2026', 100, '2026-11-14T01:17:42.168688+00:00'::timestamptz, 3, 1);
INSERT INTO "roadmap_items" ("id", "code", "title", "description", "public_description", "status", "visibility", "quarter", "progress_percent", "updated_at", "owner_id", "product_id") VALUES (5, 'RM-005', '[Internal] Tái cấu trúc Search Index & Bản đồ POI nội bộ', 'Chuyển cụm tìm kiếm sang cấu trúc chuẩn hóa không dấu tiếng Việt và tích hợp bản đồ POI chung cư nội bộ.', '', 'PLANNED', 'PRIVATE', 'Q1 2027', 5, '2026-11-14T01:17:42.169146+00:00'::timestamptz, 2, 1);
