INSERT INTO "notifications" ("id", "event_type", "title", "message", "is_read", "created_at", "feedback_id", "recipient_id") VALUES (1, 'FEEDBACK_RECEIVED', '[CRITICAL] Phản hồi mới về lỗi thanh toán', 'Khách hàng Nguyễn Hoài An vừa báo lỗi không thể thanh toán đơn hàng bằng thẻ Visa.', FALSE, '2026-11-14T01:17:42.169630+00:00'::timestamptz, 1, 2);
INSERT INTO "notifications" ("id", "event_type", "title", "message", "is_read", "created_at", "feedback_id", "recipient_id") VALUES (2, 'INSIGHT_CONFIRMED', 'Insight INS-001 cần xử lý khẩn cấp', 'Nhóm vấn đề thanh toán đạt điểm ưu tiên 90.8/100 (CRITICAL) và đã được chuyển sang In Progress.', FALSE, '2026-11-14T01:17:42.169975+00:00'::timestamptz, NULL, 3);
INSERT INTO "notifications" ("id", "event_type", "title", "message", "is_read", "created_at", "feedback_id", "recipient_id") VALUES (3, 'ROADMAP_UPDATED', 'Phản hồi của bạn đang được xử lý trên Lộ trình Sản phẩm', 'Hạng mục ''Ổn định cổng thanh toán & đối soát tự động'' đang ở trạng thái In Progress (65%).', FALSE, '2026-11-14T01:17:42.170180+00:00'::timestamptz, 1, 5);
INSERT INTO "notifications" ("id", "event_type", "title", "message", "is_read", "created_at", "feedback_id", "recipient_id") VALUES (4, 'ISSUE_COMPLETED', 'Cải tiến về Mã giảm giá đã hoàn thành!', 'Tính năng tự động gợi ý Voucher tối ưu liên quan đến góp ý của bạn đã chính thức ra mắt.', FALSE, '2026-11-14T01:17:42.170370+00:00'::timestamptz, NULL, 8);
