CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "group_id" integer NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" timestamp with time zone NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" timestamp with time zone NOT NULL);
CREATE TABLE "feedback_sources" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "code" varchar(32) NOT NULL UNIQUE, "name" varchar(100) NOT NULL, "is_active" boolean NOT NULL);
CREATE TABLE "products" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL, "slug" varchar(160) NOT NULL UNIQUE, "description" text NOT NULL, "is_active" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "roles" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "code" varchar(32) NOT NULL UNIQUE, "name" varchar(100) NOT NULL, "description" text NOT NULL, "permissions" jsonb NOT NULL);
CREATE TABLE "tags" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(60) NOT NULL UNIQUE, "slug" varchar(70) NOT NULL UNIQUE, "color" varchar(20) NOT NULL);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(255) NOT NULL, "content_type_id" integer NOT NULL, "codename" varchar(100) NOT NULL);
CREATE TABLE "users" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "is_staff" boolean NOT NULL, "is_active" boolean NOT NULL, "date_joined" timestamp with time zone NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "full_name" varchar(150) NOT NULL, "role_id" bigint NULL, "job_title" varchar(120) NOT NULL);
CREATE TABLE "users_groups" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "users_user_permissions" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "action_time" timestamp with time zone NOT NULL, "user_id" bigint NOT NULL, "content_type_id" integer NULL, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL);
CREATE TABLE "feedbacks" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "code" varchar(24) NOT NULL UNIQUE, "title" varchar(255) NOT NULL, "content" text NOT NULL, "ai_summary" text NOT NULL, "author_id" bigint NULL, "sender_name" varchar(150) NOT NULL, "sender_email" varchar(254) NOT NULL, "product_id" bigint NOT NULL, "source_id" bigint NOT NULL, "status" varchar(24) NOT NULL, "impact_level" varchar(16) NOT NULL, "priority_score" double precision NULL, "assigned_to_id" bigint NULL, "duplicate_of_id" bigint NULL, "similarity_score" double precision NULL, "is_duplicate_confirmed" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "insight_groups" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "code" varchar(24) NOT NULL UNIQUE, "product_id" bigint NOT NULL, "title" varchar(255) NOT NULL, "description" text NOT NULL, "possible_causes" jsonb NOT NULL, "ai_recommendations" jsonb NOT NULL, "draft_customer_reply" text NOT NULL, "volume_score" double precision NOT NULL, "impact_score" double precision NOT NULL, "severity_score" double precision NOT NULL, "priority_score" double precision NOT NULL, "priority_level" varchar(16) NOT NULL, "status" varchar(24) NOT NULL, "verification_status" varchar(24) NOT NULL, "feedback_count" integer NOT NULL CHECK ("feedback_count" >= 0), "assigned_to_id" bigint NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "roadmap_items" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "code" varchar(24) NOT NULL UNIQUE, "product_id" bigint NOT NULL, "title" varchar(255) NOT NULL, "description" text NOT NULL, "public_description" text NOT NULL, "status" varchar(24) NOT NULL, "visibility" varchar(16) NOT NULL, "quarter" varchar(32) NOT NULL, "progress_percent" smallint NOT NULL CHECK ("progress_percent" >= 0), "owner_id" bigint NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "token_blacklist_outstandingtoken" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NULL, "jti" varchar(255) NOT NULL UNIQUE, "token" text NOT NULL, "created_at" timestamp with time zone NULL, "expires_at" timestamp with time zone NOT NULL);
CREATE TABLE "feedback_tags" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "feedback_id" bigint NOT NULL, "tag_id" bigint NOT NULL, CONSTRAINT "unique_feedback_tag" UNIQUE ("feedback_id", "tag_id"));
CREATE TABLE "insight_feedbacks" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "insight_group_id" bigint NOT NULL, "feedback_id" bigint NOT NULL, "similarity_to_centroid" double precision NULL, CONSTRAINT "unique_insight_feedback" UNIQUE ("insight_group_id", "feedback_id"));
CREATE TABLE "notifications" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "recipient_id" bigint NOT NULL, "event_type" varchar(32) NOT NULL, "title" varchar(255) NOT NULL, "message" text NOT NULL, "feedback_id" bigint NULL, "is_read" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "roadmap_item_insights" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "roadmap_item_id" bigint NOT NULL, "insight_group_id" bigint NOT NULL, CONSTRAINT "unique_roadmap_insight" UNIQUE ("roadmap_item_id", "insight_group_id"));
CREATE TABLE "token_blacklist_blacklistedtoken" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "token_id" bigint NOT NULL UNIQUE, "blacklisted_at" timestamp with time zone NOT NULL);
CREATE TABLE "votes" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "feedback_id" bigint NULL, "insight_group_id" bigint NULL);

